head='''/*
 * Stand-in for the shared token sheet (docs/ui-guidelines/01-foundations.md).
 * Holds only the tokens this page uses; delete it once the shared sheet is linked.
 */
:root {
  --color-slate-50: #f7f8f9;
  --color-slate-100: #eff1f3;
  --color-slate-300: #c1c7d0;
  --color-slate-400: #a2abb9;
  --color-slate-600: #556276;
  --color-slate-900: #282e37;
  --color-blue-50: #f5f8fe;
  --color-blue-500: #3b82f6;
  --color-blue-600: #326ed1;
  --color-red-50: #fef5f5;
  --color-red-700: #a72f2f;

  --surface-panel: #ffffff;
  --surface-hover: var(--color-slate-100);
  --surface-selected: var(--color-blue-50);
  --border-default: var(--color-slate-300);
  --border-strong: var(--color-slate-400);
  --border-focus: var(--color-blue-500);
  --text-primary: var(--color-slate-900);
  --text-secondary: var(--color-slate-600);
  --accent-fill: var(--color-blue-600);
  --danger-text: var(--color-red-700);
  --danger-subtle: var(--color-red-50);

  --space-0: 0;
  --space-1: 0.125rem;
  --space-2: 0.25rem;
  --space-4: 0.5rem;
  --space-5: 0.75rem;
  --space-6: 1rem;
  --space-7: 1.25rem;
  --space-8: 1.5rem;

  --font-sans: "Inter", system-ui, -apple-system, "Segoe UI", sans-serif;
  --type-body: 400 0.9375rem/1.55 var(--font-sans);
  --type-body-sm: 400 0.8125rem/1.5 var(--font-sans);
  --type-body-sm-tracking: 0.005em;
  --type-label: 500 0.875rem/1.4 var(--font-sans);

  --radius-sm: 4px;
  --radius-md: 6px;
  --border-width-hairline: 1px;
  --border-width-thick: 2px;
  --duration-fast: 120ms;
  --ease-standard: cubic-bezier(0.2, 0, 0, 1);
}

'''
tail='''
/* Filters */

.filters {
  display: flex;
  flex-direction: column;
  gap: var(--space-8);
  margin-block: var(--space-8);
  color: var(--text-primary);
  font: var(--type-body);
}

.field-label {
  display: block;
  margin-block-end: var(--space-4);
  padding: var(--space-0);
  font: var(--type-label);
}

.button-row,
.field-row,
.checkbox-list {
  display: flex;
  flex-wrap: wrap;
}

.button-row {
  gap: var(--space-5) var(--space-7);
}

.field-row {
  align-items: flex-start;
  gap: var(--space-5) var(--space-6);
}

.field-row .button {
  /* Line the button up with the controls, not their labels. */
  margin-block-start: calc(0.875rem * 1.4 + var(--space-4));
}

.types {
  margin: var(--space-0);
  padding: var(--space-0);
  border: none;
  min-inline-size: 0;
}

.checkbox-list {
  gap: var(--space-0) var(--space-6);
}

.checkbox-list label {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  padding-block: var(--space-2);
  cursor: pointer;
}

.checkbox-list input {
  margin: var(--space-0);
  inline-size: var(--space-6);
  block-size: var(--space-6);
  border-radius: var(--radius-sm);
  accent-color: var(--accent-fill);
}

.button,
.filters input[type="date"],
.filters select {
  padding: var(--space-4) var(--space-5);
  border: var(--border-width-hairline) solid var(--border-default);
  border-radius: var(--radius-md);
  background: var(--surface-panel);
  color: var(--text-primary);
  font: var(--type-label);
  transition: border-color var(--duration-fast) var(--ease-standard),
    background-color var(--duration-fast) var(--ease-standard);
}

.filters input[type="date"],
.filters select {
  font: var(--type-body);
  max-inline-size: 100%;
}

.button {
  cursor: pointer;
}

.button:hover,
.filters input[type="date"]:hover,
.filters select:hover {
  border-color: var(--border-strong);
  background: var(--surface-hover);
}

/* Pressed: color plus a thicker outline, so the state never rests on color alone. */
.button[aria-pressed="true"] {
  border-color: var(--border-strong);
  background: var(--surface-selected);
  box-shadow: inset 0 0 0 var(--border-width-hairline) var(--border-strong);
}

.filters input[aria-invalid="true"] {
  border: var(--border-width-thick) solid var(--danger-text);
  background: var(--danger-subtle);
}

.field-error {
  margin: var(--space-2) var(--space-0) var(--space-0);
  color: var(--danger-text);
  font: var(--type-body-sm);
  letter-spacing: var(--type-body-sm-tracking);
}

.filter-status {
  margin: var(--space-0);
  color: var(--text-secondary);
}

.filters :focus-visible {
  outline: var(--border-width-thick) solid var(--border-focus);
  outline-offset: var(--border-width-thick);
}

#activity-table td {
  font-variant-numeric: tabular-nums;
}

@media (prefers-reduced-motion: reduce) {
  .filters * {
    transition: none;
  }
}
'''
open(p,'w').write(head+s+tail)
EOF
